use crate::aap::caps::inference_llm;
use crate::aap::caps::types::Intent;

/// `ensures len(question) <= 512`, counted in code points as Python's `len` does.
const QUESTION_MAX_CHARS: usize = 512;

const SYSTEM_PROMPT: &str = "Classify the customer message into exactly one of these labels: \
billing_question, technical_support, account_change, general_inquiry. \
If none of them applies, answer unknown. \
Reply with the label only and nothing else.";

struct Node;

/// Maps the model's reply onto the closed intent set. Anything that is not
/// exactly one of the known labels becomes `Unknown`, so adversarial model
/// output cannot widen the intent set.
fn parse_intent(reply: &str) -> Intent {
    let label = reply
        .trim()
        .trim_end_matches('.')
        .to_ascii_lowercase();
    match label.as_str() {
        "billing_question" => Intent::BillingQuestion,
        "technical_support" => Intent::TechnicalSupport,
        "account_change" => Intent::AccountChange,
        "general_inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

/// Bounds the question to at most 512 code points. Truncating on `char`
/// boundaries keeps the result valid UTF-8.
fn bounded_question(text: &str) -> String {
    text.chars().take(QUESTION_MAX_CHARS).collect()
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // The requires clause (len(text) <= 4000) holds of every input, so the
        // full text can be passed to the model as the prompt.
        let reply = inference_llm::infer(SYSTEM_PROMPT, &message.text, "classify");
        let intent = parse_intent(&reply);
        let question = bounded_question(&message.text);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
